mapper.select:
SELECT count(1) FROM `changelog_audit` a LEFT JOIN `changelog_audit_detail` b ON b.`hash` = a.`sql_hash` WHERE a.`tenant_uuid` = #{tenantUuid}
AND a.`version` LIKE concat('%', #{version}, '%')
AND a.`sql_status` = #{sqlStatus}
AND b.`sql` LIKE concat('%', #{keyword}, '%')

SELECT a.`version`, a.`tenant_uuid` AS tenantUuid, a.`module_id` AS moduleId, a.`sql_hash` AS sqlHash, a.`sql_status` AS sqlStatus, a.`error_msg` AS errorMsg, a.`ignored`, a.`lcd`, b.`sql` FROM `changelog_audit` a LEFT JOIN `changelog_audit_detail` b ON b.`hash` = a.`sql_hash` WHERE a.`tenant_uuid` = #{tenantUuid}
AND a.`version` LIKE concat('%', #{version}, '%')
AND a.`sql_status` = #{sqlStatus}
AND b.`sql` LIKE concat('%', #{keyword}, '%')
ORDER BY a.`lcd` DESC LIMIT #{startNum},#{pageSize}
